\begin{aligned}
\mathsf{Rule}_{Base}^{G}
= {}&\{(\langle\rangle,\Gamma\vdash X\ \mathsf{type}):X\in\mathsf{TVar}_{\mathsf G}\}\\
&\cup\{(\langle\rangle,\Gamma\vdash b\ \mathsf{type}):b\in\mathsf{Base}_{\mathsf G}\}\\
