\mathsf{Rule}_{Pi}^{G}
=\{(\langle\Gamma\vdash A\ \mathsf{type},\Gamma,x:A\vdash B\ \mathsf{type}\rangle,
\Gamma\vdash\Pi x:A.B\ \mathsf{type})\}
\cup
\{(\langle\Gamma,x:A\vdash t:B\rangle,\Gamma\vdash\lambda x.t:\Pi x:A.B)\}
\cup
\{(\langle\Gamma\vdash f:\Pi x:A.B,\Gamma\vdash a:A\rangle,\Gamma\vdash f\,a:B[x:=a])\},

\mathsf{Rule}_{Sigma}^{G}
=\{(\langle\Gamma\vdash A\ \mathsf{type},\Gamma,x:A\vdash B\ \mathsf{type}\rangle,
\Gamma\vdash\Sigma x:A.B\ \mathsf{type})\}
\cup
\{(\langle\Gamma\vdash a:A,\Gamma\vdash b:B[x:=a]\rangle,
\Gamma\vdash\langle a,b\rangle:\Sigma x:A.B)\}
\cup
\{(\langle\Gamma\vdash p:\Sigma x:A.B\rangle,\Gamma\vdash\pi_1(p):A)\}
\cup
\{(\langle\Gamma\vdash p:\Sigma x:A.B\rangle,\Gamma\vdash\pi_2(p):B[x:=\pi_1(p)])\},
